SELECT COUNT(DISTINCT eixo_1.calculation_838513981462429699) AS ctd:calculation_838513981462429699:ok FROM eixo_1 WHERE ((eixo_1.municipio_do_local_da_oferta = 'Uberlândia') AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA'))) AND (eixo_1.subtipo_curso = 'FIC') AND (eixo_1.uf_do_local_da_oferta = 'MG') AND (CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) IN (2011, 2012, 2013, 2014))) HAVING (COUNT(1) > 0);
